def shape_of(rows: list[list[float]]) -> tuple[int, int]:
    if not rows:
        return (0, 0)

    width = len(rows[0])
    for row in rows:
        if len(row) != width:
            raise ValueError("Every row must be the same length; this is not a matrix.")
    return (len(rows), width)

def unit_rows(X: np.ndarray) -> np.ndarray:
    lengths = np.sqrt(np.sum(X ** 2, axis=1, keepdims=True))
    if np.any(lengths == 0):
        raise ValueError("A row of length zero has no direction to keep.")
    return X / lengths

def pairwise_distances(X: np.ndarray) -> np.ndarray:
    diffs = X[:, None, :] - X[None, :, :]
    return np.sqrt(np.sum(diffs ** 2, axis=-1))
